with open('region.fasta') as f:
    lines = f.read().splitlines()
seq = ''.join(lines[1:]).upper()
comp = str.maketrans('ACGT','TGCA')
rc = seq.translate(comp)[::-1]

# proper ORF scan: ATG to stop, all frames, both strands, min 60 aa
stopp=('TAA','TAG','TGA')
def scan(s, strand):
    res=[]
    for frame in range(3):
        i=frame
        while i+3<=len(s):
            if s[i:i+3]=='ATG':
                j=i
                while j+3<=len(s):
                    if s[j:j+3] in stopp:
                        if (j-i)>=180:
                            res.append((strand, i+1, j+3, (j-i)//3))
                        break
                    j+=3
            i+=3
    return res
allr = scan(seq,'+') + scan(rc,'-')
allr.sort(key=lambda x:-x[3])
for r in allr[:12]: print(r)

# tandem repeats: exact repeated kmers len>=12
def repfind(s, k=12):
    from collections import defaultdict
    d=defaultdict(list)
    for i in range(len(s)-k+1):
        d[s[i:i+k]].append(i+1)
    hits=[(kmer,pos) for kmer,pos in d.items() if len(pos)>1]
    return hits
hits = repfind(seq)
print('\\n>=12mer exact repeats:', len(hits))
for kmer,pos in hits[:8]:
    print(kmer, pos)

# inverted repeats palindromes min 10
def pal(s,k=10):
    res=[]
    for i in range(len(s)-2*k+1):
        a=s[i:i+k]; b=s[i+k:i+2*k]
        if a==b.translate(comp)[::-1]:
            res.append((i+1,i+2*k))
    return res
print('\\ninverted repeats (10+10):')
for p in pal(seq)[:10]: print(p)

# GC skew
print('\\nGC skew (1000bp):')
for i in range(0,3000,500):
    s=seq[i:i+500]
    g,c=s.count('G'),s.count('C')
    print(i+1,i+500, round((g-c)/(g+c),3))
